import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Crpw6aS5.js";const k=JSON.parse('{"title":"Android Mobile Client","description":"","frontmatter":{},"headers":[],"relativePath":"en/mobile/index.md","filePath":"en/mobile/index.md","lastUpdated":1781423278000}'),s={name:"en/mobile/index.md"};function o(r,e,d,l,h,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="android-mobile-client" tabindex="-1">Android Mobile Client <a class="header-anchor" href="#android-mobile-client" aria-label="Permalink to &quot;Android Mobile Client&quot;">​</a></h1><p>EchoFlow Code Mobile is a remote Android client. It does not run the coding agent or desktop sidecar on the phone. Instead, it connects to a running EchoFlow Desktop / local server by scanning a launch link or entering a Server URL and H5 Token, then opens the existing H5 chat UI in a WebView.</p><p>It fits these workflows:</p><ul><li>Continue sessions, send messages, and approve tool permissions from a phone on a trusted LAN.</li><li>Reach your own desktop through HTTPS reverse proxy, VPN, Tailscale, frp, or Cloudflare Tunnel.</li><li>Use a native shell for QR scanning, credential storage, file picker, clipboard, and approval prompts.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td>Native Android connect screen</td><td>Server URL + H5 Token</td></tr><tr><td>Desktop QR launch link</td><td>Supported</td></tr><tr><td>H5 Token verification</td><td>Checks <code>/health</code> and <code>/api/h5-access/verify</code> before WebView</td></tr><tr><td>Credential storage</td><td>SecureStore</td></tr><tr><td>Permission approvals</td><td>Native approval modal bridge</td></tr><tr><td>File input</td><td>Native document picker bridge</td></tr><tr><td>Clipboard</td><td>Native clipboard bridge</td></tr><tr><td>iOS</td><td>Not release-validated yet</td></tr><tr><td>Running sidecar on phone</td><td>Not supported</td></tr></tbody></table><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><ol><li>Start EchoFlow Desktop or the local server on your computer.</li><li>Open <code>Settings -&gt; General -&gt; H5 Access</code>, enable H5, and generate a Token.</li><li>Make sure the Android device can reach the service, for example <code>http://&lt;desktop LAN IP&gt;:&lt;port&gt;/health</code>.</li><li>Show or copy the desktop H5 QR launch link.</li><li>Open EchoFlow Code Mobile and scan the link, or enter the Server URL and H5 Token manually.</li><li>After verification, the app opens the H5 WebView with chat, tool calls, approvals, and attachments.</li></ol><p>If the launch link contains <code>127.0.0.1</code> or <code>localhost</code>, the phone cannot reach it. Use the computer&#39;s LAN IP, VPN address, or HTTPS domain instead.</p><h2 id="network-notes" tabindex="-1">Network Notes <a class="header-anchor" href="#network-notes" aria-label="Permalink to &quot;Network Notes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommended path</th></tr></thead><tbody><tr><td>Same Wi-Fi testing</td><td>Desktop LAN IP + H5 Token</td></tr><tr><td>Personal remote access</td><td>VPN, Tailscale, frp, or Cloudflare Tunnel</td></tr><tr><td>Small-team access</td><td>HTTPS reverse proxy with explicit allowed origins</td></tr><tr><td>Public Internet exposure</td><td>Avoid direct exposure; use HTTPS, strong Token handling, trusted members, and minimal origin allowlists</td></tr></tbody></table><p>The H5 Token is sent with REST and WebSocket requests. Plain HTTP is acceptable only on trusted LANs; use HTTPS for untrusted networks.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><p>Mobile source lives in <code>mobile/</code>. MVP 0 is tested with JDK 17:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mobile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span></span></code></pre></div><p>If Expo CLI is unstable under Bun on Windows, use <code>npx expo start</code> and <code>npx expo run:android</code> as a fallback.</p><h2 id="mobile-vs-im-adapters" tabindex="-1">Mobile vs IM Adapters <a class="header-anchor" href="#mobile-vs-im-adapters" aria-label="Permalink to &quot;Mobile vs IM Adapters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Best entry</th></tr></thead><tbody><tr><td>Full chat UI, approvals, and file upload on a phone</td><td>Android client or mobile browser H5</td></tr><tr><td>Quick task submission, progress checks, and stop commands in chat tools</td><td>Telegram / Feishu / WeChat / DingTalk adapters</td></tr><tr><td>Shared team access</td><td>HTTPS reverse proxy + H5 origin allowlist, or IM user pairing</td></tr></tbody></table><p>The Android client and IM adapters can be used together: mobile H5 is best for continuing the UI, while IM is best for lightweight commands and async notifications.</p>`,19)])])}const b=t(s,[["render",o]]);export{k as __pageData,b as default};
